using System;using System.IO;using System.Collections.Generic;using System.Security.Cryptography;
class QuestProgressionFixturesFG {
 static void Check(bool ok,string label){if(!ok)throw new InvalidDataException("Fixture failed: "+label);}
 static string Hash(string path){using(SHA256 h=SHA256.Create())return Convert.ToBase64String(h.ComputeHash(File.ReadAllBytes(path)));}
 delegate void Attempt();static void Reject(Attempt action,string path,string label){string before=Hash(path);bool rejected=false;try{action();}catch(InvalidDataException){rejected=true;}Check(rejected&&Hash(path)==before,label);}
