  string materialPath=Path.Combine(output,"material.xml");Offline70QuestDefinitionFG material=catalog.Get(1146);Offline70ProgressionStateFG m=new Offline70ProgressionStateFG{Experience=Offline70ProgressionFG.Threshold(5)};foreach(Offline70QuestIdsFG group in material.Prerequisites)foreach(ushort id in group.Ids)if(!m.Completed.Contains(id))m.Completed.Add(id);Offline70QuestEngineFG.Seed(materialPath,m);m=engine.Accept(materialPath,1146);
