  Reject(delegate{engine.Complete(materialPath,1146,material.CompleteNpc>=0?material.CompleteNpc:material.Npc,ushort.MaxValue,"collection-short");},materialPath,"material short no reward");
  m=engine.Collect(materialPath,3015,1,"material-bone-fifth");m=engine.Complete(materialPath,1146,material.CompleteNpc>=0?material.CompleteNpc:material.Npc,ushort.MaxValue,"quest-1146-complete-1");Check(m.Count(3015)==0&&m.Gold==324&&m.Outbox[0].ExperienceCredit==312&&m.Count(20002)==1&&m.Outbox[0].Debits[0].Quantity==5,"real materials consumed and rewards atomically committed");
  string projectionPath=Path.Combine(output,"projection.xml");Offline70QuestEngineFG.Seed(projectionPath,new Offline70ProgressionStateFG());List<Offline70ItemCountFG> assets=new List<Offline70ItemCountFG>();assets.Add(new Offline70ItemCountFG{Id=3015,Quantity=2});assets.Add(new Offline70ItemCountFG{Id=3015,Quantity=3});Offline70ProgressionStateFG projected=Offline70QuestEngineFG.SyncAssets(projectionPath,169,396,assets);Check(projected.Count(3015)==5&&projected.Gold==169&&projected.Experience==396,"authoritative asset projection merges slots");before=Hash(projectionPath);Offline70QuestEngineFG.SyncAssets(projectionPath,169,396,assets);Check(Hash(projectionPath)==before,"identical projection does not rewrite state");assets.Clear();projected=Offline70QuestEngineFG.SyncAssets(projectionPath,169,396,assets);Check(projected.Count(3015)==0,"used or removed material no longer satisfies old projection");Reject(delegate{Offline70QuestEngineFG.SyncAssets(projectionPath,uint.MaxValue,396,assets);},projectionPath,"invalid authoritative balance rejects without write");
  Offline70QuestDefinitionFG dropQuest=null;foreach(Offline70QuestDefinitionFG q in catalog.Definitions.Values)if(q.Supported&&q.Job=="[all]"&&q.GrowType<0&&q.MonsterDrops.Length>=7&&q.MonsterDrops[5]>0&&q.MonsterDrops[6]>0&&q.MinLevel<=70){dropQuest=q;break;}Check(dropQuest!=null,"active quest material drop catalog");string dropPath=Path.Combine(output,"drops.xml");Offline70ProgressionStateFG dropState=new Offline70ProgressionStateFG{Experience=dropQuest.MinLevel<=1?0:Offline70ProgressionFG.Threshold((byte)dropQuest.MinLevel)};foreach(Offline70QuestIdsFG group in dropQuest.Prerequisites)foreach(ushort id in group.Ids)if(!dropState.Completed.Contains(id))dropState.Completed.Add(id);Offline70QuestEngineFG.Seed(dropPath,dropState);dropState=engine.Accept(dropPath,dropQuest.Id);int[] drop=dropQuest.MonsterDrops;List<Offline70QuestDropFG> plans=Offline70QuestDropsFG.Monster(catalog,dropState,drop[0],drop[1]<0?1:drop[1],drop[2]<0?0:drop[2],0);Check(plans.Count>0&&plans[0].ItemId==drop[3],"real active quest matching monster material plan");dropState.SetCount(drop[3],(uint)drop[6]);plans=Offline70QuestDropsFG.Monster(catalog,dropState,drop[0],drop[1]<0?1:drop[1],drop[2]<0?0:drop[2],0);foreach(Offline70QuestDropFG plan in plans)Check(plan.ItemId!=drop[3],"quest material maximum prevents duplicate extra drop");
  int boundaries=0;for(byte l=2;l<=70;l++){uint t=Offline70ProgressionFG.Threshold(l);Check(Offline70ProgressionFG.Level(t-1)==l-1&&Offline70ProgressionFG.Level(t)==l,"current PVF level boundary"+l);boundaries++;}
  Check(Offline70ProgressionFG.AddExperience(Offline70ProgressionFG.Threshold(70)-1,uint.MaxValue)==Offline70ProgressionFG.Threshold(70)&&Offline70ProgressionFG.WithinLevel(Offline70ProgressionFG.Threshold(70))==0,"overflow-safe level70 cap");
  for(byte l=1;l<=70;l++){byte[] stats=Offline70SwordmanGrowthFG.Stats(0,l);Check(stats.Length==87&&BitConverter.ToUInt32(stats,0)==1940+590*(l-1)&&BitConverter.ToSingle(stats,83)==0,"current PVF swordman growth87bytes");}
  Check(Offline70QuestCatalogFG.AcceptBody(101,1)[1]==101&&Offline70QuestCatalogFG.ProgressBody(101,0).Length==7&&Offline70QuestCatalogFG.FinishBody(101).Length==11,"fixed101 body compatibility");
  string repeatPath=Path.Combine(output,"repeat.xml");Offline70QuestDefinitionFG repeated=catalog.Get(408);Offline70ProgressionStateFG repeat=new Offline70ProgressionStateFG{Experience=Offline70ProgressionFG.Threshold(47)};foreach(Offline70QuestIdsFG group in repeated.Prerequisites)foreach(ushort id in group.Ids)if(!repeat.Completed.Contains(id))repeat.Completed.Add(id);repeat.SetCount(3187,20);Offline70QuestEngineFG.Seed(repeatPath,repeat);repeat=engine.Accept(repeatPath,408);string firstInstance=repeat.Find(408).Instance,firstReceipt=Offline70QuestEngineFG.CompletionReceipt(repeat,408);before=Hash(repeatPath);engine.Accept(repeatPath,408);Check(Hash(repeatPath)==before&&Offline70QuestEngineFG.CompletionReceipt(Offline70QuestEngineFG.Load(repeatPath),408)==firstReceipt,"duplicate accept and restart preserve completion instance");repeat=engine.Complete(repeatPath,408,26,ushort.MaxValue,firstReceipt);Check(repeat.Count(4083)==1&&Offline70QuestEngineFG.CompletionReceipt(repeat,408)==firstReceipt,"completed instance receipt recoverable from outbox");repeat=engine.Accept(repeatPath,408);string secondReceipt=Offline70QuestEngineFG.CompletionReceipt(repeat,408);Check(repeat.Find(408).Instance!=firstInstance&&secondReceipt!=firstReceipt,"repeat accept generates persisted new instance");repeat=engine.Complete(repeatPath,408,26,ushort.MaxValue,secondReceipt);Check(repeat.Count(4083)==2&&repeat.Count(3187)==0&&repeat.Outbox.Count==2,"repeat task rewards once in each acceptance cycle");
  int unsupported=0;foreach(Offline70QuestDefinitionFG q in catalog.Definitions.Values)if(!q.Supported)unsupported++;
  File.WriteAllText(Path.Combine(output,"report.json"),"{\"allPassed\":true,\"questCount\":"+catalog.Definitions.Count+",\"supportedBackend\":"+(catalog.Definitions.Count-unsupported)+",\"levelBoundaries\":"+boundaries+",\"testedQuestIds\":[102,103,1146],\"persistedGold\":580,\"scope\":\"Offline atomic backend and packet bodies; not native end-to-end gameplay\"}");Console.WriteLine("PASS current PVF catalog"+catalog.Definitions.Count+", quests102/103/1146, atomic chosen rewards/material costs/outbox/receipts, all69 level boundaries");return 0;
